CREATE TABLE t3(a TEXT,b TEXT,c INTEGER);WITH d(j)AS(VALUES('[[934,911,239,223],[309,572,870,627],[399,660,412,247,762,393],[792,840,633,705,711,786],[158,759,430,607],[822,346],[845,224,256],[716,794,959,238],[113,777],[629,252,768],[670,208,618,667],[938,870,574,295,726,102],[480,148,634,335],[929,844,938,160],[480,979,790],[355,963,330,730,133,683],[398,652],[421,250,671,443,805],[768,899,234,113],[354,257,336,839]]'))INSERT INTO t3 SELECT char(65+p.key/2)||char(65+p.key/2),CASE p.key%2 WHEN 0 THEN'aa'ELSE'bb'END,q.value FROM d,json_each(d.j)p,json_each(p.value)q;